package com.erni.finalanswer.lastcommand;
public final class NumberInputPreviewCheck {
    private static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
    public static void main(String[] args){
        var p=new NumberInputPreview();p.snapshot("t","","",false);p.queue("a","1");p.queue("b","2");check(p.value().equals("12"),"Immediate burst");p.snapshot("t","1","",false);check(p.value().equals("12"),"Broadcast before ACK must not double apply");p.snapshot("t","1","a",false);check(p.value().equals("12")&&p.count()==1,"First ACK retains next key");p.queue("c","DELETE");check(p.value().equals("1"),"Immediate delete");p.snapshot("t","12","",false);check(p.value().equals("1"),"Later broadcast cannot rewind edit");p.snapshot("t","12","b",false);check(p.value().equals("1"),"Rebase delete on acknowledged prefix");p.snapshot("t","1","c",false);check(p.count()==0&&p.value().equals("1"),"Final ACK settles");
        p.queue("d","CLEAR");p.queue("e","-");p.queue("f","3");check(p.value().equals("-3"),"Clear/minus/type burst");p.snapshot("t","","d",false);p.snapshot("t","-","e",false);p.snapshot("t","-3","f",false);check(p.value().equals("-3")&&p.count()==0,"Signed input settles");check(NumberInputPreview.edit("3","-").equals("3"),"Minus only at start");check(NumberInputPreview.edit("123456789","0").equals("123456789"),"Same nine-character limit as server");
        p.queue("g","9");p.snapshot("new","7","",false);check(p.value().equals("7")&&p.count()==0,"Task replacement drops stale local edits");p.queue("h","8");p.snapshot("new","78","",false);p.cancel();check(p.value().equals("78")&&p.count()==0,"Rejection/disconnect rollback to latest authority");p.queue("i","DELETE");p.snapshot("new","78","",true);check(p.value().equals("78")&&p.count()==0,"Pause/verdict discards unsent projection");for(int i=0;i<100;i++)p.queue("bounded-"+i,"1");check(p.count()==64,"Bounded queue");p.cancel();System.out.println("NUMBER_INPUT_PREVIEW_OK: immediate burst, broadcast/ACK ordering, delete/clear/minus, limits, cancellation, task replacement, bounded queue");
    }
}
